    static let ru: [String: [String]] = {
        var map: [String: [String]] = [:]
        for line in raw.split(separator: "\n") {
            let parts = line.split(separator: "\t", maxSplits: 1)
            if parts.count == 2 { map[String(parts[0])] = parts[1].split(separator: "|").map(String.init) }
        }
        return map
    }()

    /// Стабильный хэш (у `String.hashValue` в Swift — случайное зерно на запуск): формулировка у фильма не меняется.
    private static func stableHash(_ s: String) -> Int {
        var h: UInt64 = 1469598103934665603
        for b in s.utf8 { h = (h ^ UInt64(b)) &* 1099511628211 }
        return Int(h % 1_000_003)
    }

    /// Метки фильма: сильнейшие тонкие черты (не ниже 2), из разных групп, общие — в конце, черта группы `prefer` — первой.
    static func tags(_ id: String, _ profile: [String: Int], english: Bool, count: Int = 2, prefer: String? = nil) -> [String] {
        var seenGroups = Set<String>()
        let sorted = profile.filter { $0.value >= 2 && RelativeCriteria.criterion($0.key) != nil }.sorted { a, b in
            let pa = RelativeCriteria.criterion(a.key)!.group == prefer, pb = RelativeCriteria.criterion(b.key)!.group == prefer
            if pa != pb { return pa }
            let ga = RelativeCriteria.generic.contains(a.key), gb = RelativeCriteria.generic.contains(b.key)
            if ga != gb { return !ga }
            return a.value != b.value ? a.value > b.value : a.key < b.key
        }
        return sorted.filter { seenGroups.insert(RelativeCriteria.criterion($0.key)!.group).inserted }.prefix(count).compactMap { entry in
            if english { return RelativeCriteria.criterion(entry.key)?.en }
            guard let list = ru[entry.key], !list.isEmpty else { return nil }
            return list[stableHash(id + "|" + entry.key) % list.count]
        }
    }

    static func label(_ id: String, _ profile: [String: Int], english: Bool, prefer: String? = nil) -> String {
        let text = tags(id, profile, english: english, prefer: prefer).joined(separator: " · ")
        return text.prefix(1).uppercased() + text.dropFirst()
    }
